// Persistence context lifecycle demonstration:
@Transactional
public void updateUserName(Long userId, String newName) {
    User user = entityManager.find(User.class, userId); // entity is now MANAGED
    user.setName(newName);  // just a Java setter — no save() call needed!
    // At transaction commit: Hibernate detects change, issues:
    // UPDATE users SET name = ? WHERE id = ?
}

// Entity lifecycle states:
// NEW      — created with new User(), no ID, unknown to persistence context
// MANAGED  — has ID, tracked by persistence context, changes auto-persisted
// DETACHED — had a persistence context, but it's closed (e.g., after tx)
// REMOVED  — scheduled for deletion at next flush

@Entity
@Table(name = "products",
       uniqueConstraints = @UniqueConstraint(columnNames = "sku"))
public class Product {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "product_name", nullable = false, length = 200)
    private String name;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal price;

    @Column(name = "sku", unique = true, length = 50)
    private String sku;

    @Column(name = "in_stock")
    private boolean inStock = true;

    @Transient  // not persisted to DB
    private String displayLabel;

    // JPA requires a no-args constructor (can be protected)
    protected Product() {}

    public Product(String name, BigDecimal price, String sku) { ... }
}

// IDENTITY (MySQL, SQL Server — cannot batch INSERTs):
@Id @GeneratedValue(strategy = GenerationType.IDENTITY)
private Long id;

// SEQUENCE (PostgreSQL — supports batching, preferred):
@Id
@GeneratedValue(strategy = GenerationType.SEQUENCE,
                generator = "product_seq")
@SequenceGenerator(name = "product_seq",
                   sequenceName = "product_id_seq",
                   allocationSize = 50)   // fetch 50 IDs per round trip
private Long id;

// UUID (Hibernate 6+):
@Id
@UuidGenerator
private UUID id;

