// Custom converter: store Money as a long (cents) in the DB:
@Converter(autoApply = true)
public class MoneyConverter implements AttributeConverter<Money, Long> {
    @Override
    public Long convertToDatabaseColumn(Money money) {
        return money == null ? null : money.getCents();
    }
    @Override
    public Money convertToEntityAttribute(Long cents) {
        return cents == null ? null : Money.ofCents(cents);
    }
}

@Entity
public class User {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Owning side — holds the foreign key column
    @OneToOne(cascade = CascadeType.ALL, orphanRemoval = true)
    @JoinColumn(name = "profile_id", referencedColumnName = "id")
    private UserProfile profile;
}

@Entity
public class UserProfile {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Non-owning side — no FK here, just a navigation reference
    @OneToOne(mappedBy = "profile")
    private User user;
}

// Shared primary key (profile ID == user ID):
@Entity
public class UserSettings {
    @Id
    private Long id;  // same value as User.id

    @OneToOne
    @PrimaryKeyJoinColumn  // JOIN ON user.id = user_settings.id
    private User user;
}

@Entity
public class Order {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Non-owning side — mappedBy points to the field in OrderItem
    @OneToMany(mappedBy = "order",
               cascade = CascadeType.ALL,
               orphanRemoval = true,
               fetch = FetchType.LAZY)  // LAZY is default for collections
    private List<OrderItem> items = new ArrayList<>();

    // Helper method to keep both sides in sync:
    public void addItem(OrderItem item) {
        items.add(item);
        item.setOrder(this);  // set the owning side!
    }
}

@Entity
public class OrderItem {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Owning side — holds the FK column
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id", nullable = false)
    private Order order;

    private int quantity;
    private BigDecimal price;
}

@Entity
public class Student {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Owning side — defines the join table
    @ManyToMany
    @JoinTable(
        name = "student_course",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}

@Entity
public class Course {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Inverse side
    @ManyToMany(mappedBy = "courses")
    @JsonIgnore  // prevent infinite recursion
    private Set<Student> students = new HashSet<>();
}

