// Choosing cascade types deliberately:
@Entity
public class BlogPost {

    // Comments owned by the post — cascade ALL + orphanRemoval
    @OneToMany(mappedBy = "post",
               cascade = CascadeType.ALL,
               orphanRemoval = true)  // removing from list deletes from DB
    private List<Comment> comments = new ArrayList<>();

    // Tags are shared entities — only cascade PERSIST and MERGE, NOT REMOVE
    // (deleting a Post should not delete the Tag itself)
    @ManyToMany(cascade = {CascadeType.PERSIST, CascadeType.MERGE})
    private Set<Tag> tags = new HashSet<>();
}

// Demonstrating orphanRemoval:
@Transactional
public void removeComment(Long postId, Long commentId) {
    BlogPost post = postRepo.findById(postId).orElseThrow();
    post.getComments().removeIf(c -> c.getId().equals(commentId));
    // orphanRemoval = true → DELETE FROM comments WHERE id = ? fired at commit
    // No explicit commentRepo.delete() needed!
}

// Default behavior (don't rely on these blindly):
// @ManyToOne → EAGER by default (load customer with each order)
// @OneToMany → LAZY by default (load items only when accessed)

// Explicitly set to LAZY for better control:
@ManyToOne(fetch = FetchType.LAZY)  // override the EAGER default!
@JoinColumn(name = "customer_id")
private Customer customer;

@OneToMany(mappedBy = "order", fetch = FetchType.LAZY) // default, but explicit
private List<OrderItem> items;

// LAZY causes LazyInitializationException outside @Transactional:
// This FAILS if called outside a transaction:
Order order = orderRepo.findById(1L).get();
order.getItems().size();  // ← LazyInitializationException here!

// Fix: use JOIN FETCH or @EntityGraph to load items eagerly in the query

// N+1 problem:
List<Order> orders = orderRepo.findAll(); // 1 query
orders.forEach(o -> {
    System.out.println(o.getCustomer().getName()); // N queries!
});
// Total: 1 + N queries

// Fix with JOIN FETCH in repository:
public interface OrderRepository extends JpaRepository<Order, Long> {

    @Query("SELECT o FROM Order o JOIN FETCH o.customer")
    List<Order> findAllWithCustomer();

    // Join-fetch a collection (use DISTINCT to avoid duplicate parent rows):
    @Query("SELECT DISTINCT o FROM Order o JOIN FETCH o.items")
    List<Order> findAllWithItems();
}

// Caution: you cannot JOIN FETCH two collections in one query
// (Hibernate MultipleBagFetchException). Use @EntityGraph or
// separate queries if you need both customer and items.

// Define on the entity:
@NamedEntityGraph(
    name = "Order.withCustomerAndItems",
    attributeNodes = {
        @NamedAttributeNode("customer"),
        @NamedAttributeNode(value = "items", subgraph = "items-subgraph")
    },
    subgraphs = @NamedSubgraph(
        name = "items-subgraph",
        attributeNodes = @NamedAttributeNode("product")
    )
)
@Entity
public class Order { ... }

// Use in repository:
public interface OrderRepository extends JpaRepository<Order, Long> {

    // Reference named graph:
    @EntityGraph("Order.withCustomerAndItems")
    List<Order> findByStatus(OrderStatus status);

    // Or specify inline (FETCH type — only listed paths are loaded eagerly):
    @EntityGraph(attributePaths = {"customer", "items"})
    Optional<Order> findById(Long id);
}

