// Basic queries:
public interface UserRepository extends JpaRepository<User, Long> {

    // Named parameter
    @Query("SELECT u FROM User u WHERE u.email = :email")
    Optional<User> findByEmail(@Param("email") String email);

    // JOIN
    @Query("SELECT DISTINCT o FROM Order o JOIN o.items i "
         + "WHERE i.product.id = :productId")
    List<Order> findOrdersContainingProduct(@Param("productId") Long pid);

    // Aggregation
    @Query("SELECT u.department, COUNT(u) FROM User u "
         + "GROUP BY u.department HAVING COUNT(u) > :minCount")
    List<Object[]> countUsersByDepartment(@Param("minCount") long minCount);

    // @NamedQuery on the entity class:
    // @NamedQuery(name = "User.findActive",
    //             query = "SELECT u FROM User u WHERE u.active = true")
    List<User> findActive();  // method name must match query name suffix
}

// Programmatic Criteria API query:
@PersistenceContext
private EntityManager em;

public List<User> searchUsers(String name, String city, Integer minAge) {
    CriteriaBuilder cb = em.getCriteriaBuilder();
    CriteriaQuery<User> cq = cb.createQuery(User.class);
    Root<User> root = cq.from(User.class);

    List<Predicate> predicates = new ArrayList<>();
    if (name != null)
        predicates.add(cb.like(cb.lower(root.get("name")),
                               "%" + name.toLowerCase() + "%"));
    if (city != null)
        predicates.add(cb.equal(root.get("city"), city));
    if (minAge != null)
        predicates.add(cb.greaterThanOrEqualTo(root.get("age"), minAge));

    cq.where(predicates.toArray(new Predicate[0]));
    cq.orderBy(cb.asc(root.get("name")));
    return em.createQuery(cq).getResultList();
}

// Spring Data Specification (cleaner for Spring apps):
public class UserSpecs {
    public static Specification<User> hasCity(String city) {
        return (root, query, cb) -> cb.equal(root.get("city"), city);
    }
}
userRepo.findAll(UserSpecs.hasCity("London").and(UserSpecs.isActive()));

public interface ProductRepository extends JpaRepository<Product, Long> {

    // Simple equality
    Optional<Product> findBySku(String sku);

    // Multiple conditions
    List<Product> findByNameAndActiveTrue(String name);

    // Comparison
    List<Product> findByPriceLessThanEqual(BigDecimal maxPrice);

    // LIKE search
    List<Product> findByNameContainingIgnoreCase(String keyword);

    // IN clause
    List<Product> findByCategoryIn(List<String> categories);

    // Sorting + limiting
    List<Product> findTop5ByOrderByCreatedAtDesc();

    // Count and exists
    long countByCategory(String category);
    boolean existsBySku(String sku);

    // Between
    List<Product> findByPriceBetween(BigDecimal min, BigDecimal max);

    // Null check
    List<Product> findByDeletedAtIsNull();
}

public interface ProductRepository extends JpaRepository<Product, Long> {

    // JPQL with JOIN
    @Query("SELECT p FROM Product p JOIN p.category c WHERE c.name = :catName")
    List<Product> findByCategory(@Param("catName") String catName);

    // Native SQL
    @Query(value = "SELECT * FROM products WHERE FULLTEXT(name) AGAINST (:q)",
           nativeQuery = true)
    List<Product> fullTextSearch(@Param("q") String query);

    // Bulk update — must use @Modifying + @Transactional
    @Modifying
    @Transactional
    @Query("UPDATE Product p SET p.price = p.price * :factor "
         + "WHERE p.category = :cat")
    int adjustPriceByCategory(@Param("factor") BigDecimal factor,
                              @Param("cat") String category);

    // Interface projection — only loads id and name columns:
    interface ProductSummary {
        Long getId();
        String getName();
    }
    List<ProductSummary> findByActiveTrue();

    // DTO projection with constructor expression:
    @Query("SELECT new com.app.dto.ProductDto(p.id, p.name, p.price) "
         + "FROM Product p WHERE p.active = true")
    List<ProductDto> findActiveSummaries();
}

@Service
public class OrderService {

    // Default: REQUIRED propagation, rolls back on RuntimeException
    @Transactional
    public Order placeOrder(OrderRequest req) {
        Order order = orderRepo.save(new Order(req));
        inventoryService.reserveStock(req.items());  // same transaction!
        paymentService.charge(req.paymentInfo());    // same transaction!
        return order;
    }

    // REQUIRES_NEW: audit persists even if main tx rolls back
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logAuditEvent(String event) {
        auditRepo.save(new AuditLog(event));
    }

    // rollbackFor checked exception:
    @Transactional(rollbackFor = IOException.class)
    public void importData() throws IOException { ... }

    // readOnly — skip dirty checking, hint for read replica routing:
    @Transactional(readOnly = true)
    public List<Order> getOrdersByUser(Long userId) {
        return orderRepo.findByUserId(userId);
    }
}

# Disable OSIV in application.properties:
# spring.jpa.open-in-view=false

// BAD — entity escapes transaction, OSIV masks the problem:
@RestController
public class OrderController {
    @GetMapping("/orders/{id}")
    public Order getOrder(@PathVariable Long id) {
        Order order = orderService.findById(id);  // tx ends here
        // OSIV masks the lazy access below; without OSIV → exception:
        order.getItems().size();  // ← triggers hidden DB query!
        return order;             // Jackson serializes → more lazy queries!
    }
}

// GOOD — return DTO, load all data within the transaction:
@Service
public class OrderService {
    @Transactional(readOnly = true)
    public OrderDto findById(Long id) {
        Order order = orderRepo.findWithItemsAndCustomer(id);  // JOIN FETCH
        return OrderMapper.toDto(order);  // map to DTO within tx
    }
}
// Controller receives a plain DTO — no lazy loading, no session needed.

public interface ProductRepository extends JpaRepository<Product, Long> {

    // Spring auto-adds LIMIT/OFFSET:
    Page<Product> findByActiveTrue(Pageable pageable);

    // With @Query — also supports Pageable:
    @Query("SELECT p FROM Product p WHERE p.price < :maxPrice")
    Page<Product> findByMaxPrice(@Param("maxPrice") BigDecimal max,
                                 Pageable pageable);
}

@GetMapping("/products")
public Page<ProductDto> list(
        @PageableDefault(size = 20, sort = "name") Pageable pageable) {
    // Spring MVC binds: ?page=0&size=20&sort=name,asc
    return productRepository
        .findByActiveTrue(pageable)
        .map(productMapper::toDto);  // Page<Entity> → Page<Dto>
}

